INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (1, 'Administration', 'Administration', 'Administration de la mine', 'Mine Administration', 'Planification stratégique, gestion des opérations, supervision financière et conformité réglementaire.', 'Strategic planning, operations management, financial supervision and regulatory compliance.', 1, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (2, 'Ressources humaines', 'Human Resources', 'Ressources humaines', 'Human Resources', 'Les ressources humaines gèrent le personnel et contribuent à garantir un environnement de travail productif, sûr et épanouissant.', 'Human resources manage personnel and help ensure a productive, safe and fulfilling work environment.', 2, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (3, 'Sûreté', 'Security', 'Département Sécurité', 'Security Department', 'Le dispositif comprend une CCTV de 44 caméras, une cellule drone, une brigade canine, une permanence des superviseurs 24h/24.', 'The security system includes 44 CCTV cameras, a drone unit, a canine brigade, and 24/7 supervisor presence.', 3, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (4, 'Opérations', 'Operations', 'Département Mining', 'Mining Department', 'Le processus minier regroupe la planification, les études de faisabilité, l''analyse économique et les étapes techniques.', 'The mining process includes planning, feasibility studies, economic analysis and technical steps.', 4, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (5, 'HSE', 'HSE', 'Hygiène, Santé, Sécurité et Environnement', 'Health, Safety, Security and Environment', 'Le département HSE vise zéro incident grâce à la formation continue, aux inspections régulières, au suivi environnemental.', 'The HSE department aims for zero incidents through continuous training, regular inspections, and environmental monitoring.', 5, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (6, 'Traitement', 'Processing', 'Département Processing', 'Processing Department', 'Le Processing est organisé en quatre sections : opérations, maintenance des équipements fixes, métallurgie et infrastructures.', 'Processing is organized into four sections: operations, fixed equipment maintenance, metallurgy and infrastructure.', 6, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (7, 'Approvisionnement', 'Supply Chain', 'Chaîne d''approvisionnement (SCM)', 'Supply Chain Management (SCM)', 'Le SCM comprend les Achats, la Logistique, les Contrats et le Magasin. Il est dirigé par une équipe entièrement locale.', 'SCM includes Purchasing, Logistics, Contracts and Warehouse. It is managed by an entirely local team.', 7, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (8, 'Technologies', 'IT', 'Département IT', 'IT Department', 'Le département IT accompagne les équipes et les opérations de Karma grâce aux outils et services numériques.', 'The IT department supports Karma''s teams and operations through digital tools and services.', 8, true, NOW(), NOW());
INSERT INTO karma_departments (id, tag_fr, tag_en, title_fr, title_en, body_fr, body_en, sort_order, is_published, created_at, updated_at) VALUES (9, 'Dialogue local', 'Community Relations', 'Relations communautaires', 'Community Relations', 'Le département gère les impacts sociaux, entretient le dialogue avec les communautés et soutient les autorités locales.', 'The department manages social impacts, maintains dialogue with communities and supports local authorities.', 9, true, NOW(), NOW());
