INSERT INTO news (id, title, category, excerpt, image_path, published_at, created_at, updated_at) VALUES (1, 'Annulation du contrat d''achat d''or: Riverstone Karma SA salue une décision judiciaire historique du Tribunal de commerce de Ouagadougou', 'Actualités', 'Par jugement en date du 10 juin 2026, le Tribunal de commerce de Ouagadougou a statué en faveur de Riverstone Karma SA dans le différend qui l''opposait aux sociétés Franco-Nevada et Sandstorm Gold Ltd.', 'images/news/ZJ58L6cbb9z6C4qPwArMnxzy0A4RQW4doJDfc7SV.jpg', '2026-08-12', NOW(), NOW());
INSERT INTO news (id, title, category, excerpt, image_path, published_at, created_at, updated_at) VALUES (2, 'Forum Mines 2026 : Néré Mining réaffirme son engagement en faveur des pratiques durables dans l''exploitation minière', 'Événement', 'La troisième édition du Forum Mines a officiellement ouvert ses portes le mardi 7 juillet 2026 à Ouagadougou.', 'images/news/g4XciRGY5t48TKSsjdneCu5APzh3g673Q30YMnpr.jpg', '2026-08-22', NOW(), NOW());
INSERT INTO news (id, title, category, excerpt, image_path, published_at, created_at, updated_at) VALUES (3, '6ème édition de la SAMAO.', 'Partenariats', 'Nous renforçons nos partenariats avec les entreprises et organisations locales pour créer de la valeur partagée.', 'images/news/F6nUuFafpUqWZu1MKDcY5PzQbQsDXsFMXmEOVNuX.png', '2024-11-29', NOW(), NOW());